def triples(text): return [tuple(part.strip().split('|')) for part in text.replace('\n', ';').split(';') if part.strip()]
def normalize(text): return re.sub(r'\s+', ' ', text.lower()).strip(' ,.')
def save(name, value): Path('src/data/'+name+'.json').write_text(json.dumps(value, ensure_ascii=False, separators=(',', ':')), encoding='utf8', newline='\n')
def metadata(row, source_id, estimated, category=''):
    name = row['name']; text = normalize(name['en']); tags = set(row.get('tags', [])); allergens = set()
    if (category == '1' and not text.startswith('egg')) or 'dairy' in tags: tags.add('dairy'); allergens.add('milk')
    if re.search(r'\beggs?\b',text) or 'egg' in tags: allergens.add('egg')
    if ('nuts,' in text or 'nuts' in tags) and 'coconut' not in text and 'peanut' not in text: allergens.add('tree-nuts'); tags.add('nuts')
    if 'peanut' in text or 'peanut' in tags: allergens.add('peanut')
    if 'soy' in text or 'tofu' in text or 'soy' in tags: allergens.add('soy')
    if (re.search(r'\b(wheat|barley|rye|couscous|bulgur|spelt|semolina|pasta|noodles|bread|seitan)\b',text) or 'gluten' in tags) and 'gluten-free' not in text: allergens.add('gluten'); tags.add('gluten')
    if 'sesame' in text: allergens.add('sesame')
    if 'celery' in text or 'celeriac' in text: allergens.add('celery')
    if 'mustard' in text: allergens.add('mustard')
    if 'lupin' in text: allergens.add('lupin')
    if 'sulfured' in text and 'unsulfured' not in text: allergens.add('sulfites')
    if 'fish' in tags: allergens.add('fish')
    if 'shellfish' in tags: allergens.add('shellfish')
    if category == '11': tags.add('vegetable')
    if category == '9': tags.add('fruit')
    if category == '20': tags.add('starch')
    vegetarian = 'meat' not in tags and 'fish' not in tags and 'shellfish' not in tags
    return dict(row, aliases={lang:[name[lang],name['en']] if lang!='en' else [name['en']] for lang in ['ru','kk','en']}, tags=sorted(tags), portions=[{'name':{'ru':'100 граммов','kk':'100 грамм','en':'100 grams'},'grams':100}], allergens=sorted(allergens), vegetarian=vegetarian, halal='not-suitable' if 'pork' in tags or 'alcohol' in tags else 'verify' if not vegetarian or 'dairy' in tags else 'suitable', sourceId=source_id, license='CC0-1.0', estimated=estimated, translationReview='machine-assisted; native speaker review required')
def load_usda():
    ARCHIVE.parent.mkdir(exist_ok=True)
    if not ARCHIVE.exists(): urllib.request.urlretrieve(URL, ARCHIVE)
    if hashlib.sha256(ARCHIVE.read_bytes()).hexdigest()!='b80817294b8850530aaedf2e515c02593b1824f763a0ff356e5c2081643e6fd0': raise ValueError('USDA archive checksum differs; review the source before rebuilding')
    with zipfile.ZipFile(ARCHIVE) as archive:
        def read(name): return list(csv.DictReader(io.TextIOWrapper(archive.open(next(n for n in archive.namelist() if n.endswith('/'+name))),encoding='utf-8-sig')))
        nutrients={}
        for row in read('food_nutrient.csv'):
            if row['nutrient_id'] in ['1003','1004','1005','1008']: nutrients.setdefault(row['fdc_id'],{})[row['nutrient_id']]=float(row['amount'])
        return [(row,nutrients[row['fdc_id']]) for row in read('food.csv') if len(nutrients.get(row['fdc_id'],{}))==4]
def add_regional(result):
    forced={'169761':('Мука пшеничная белая, необогащённая','Байытылмаған ақ бидай ұны'),'175086':('Конина, сырая','Шикі жылқы еті'),'175087':('Конина, запечённая','Пеште піскен жылқы еті'),'171952':('Карп, сырой','Шикі тұқы'),'173468':('Соль поваренная','Ас тұзы'),'170931':('Перец чёрный молотый','Ұнтақталған қара бұрыш')}
