    families=sorted(triples(FAMILIES),key=lambda row:-len(row[0])); qualifiers={normalize(key):(ru,kk) for key,ru,kk in triples(QUALIFIERS)}; unknown={}; selected=[]
    for row,n in load_usda():
        description=row['description']; clean=re.sub(r'\s*\(Includes foods for USDA.s Food Distribution Program\)','',description,flags=re.I)
        family=next((f for f in families if normalize(clean)==normalize(f[0]) or normalize(clean).startswith(normalize(f[0])+',')),None)
        if not family: continue
        tail=clean[len(family[0]):].strip(' ,'); chunks=[normalize(s) for s in tail.split(',') if normalize(s)]
        if any(s not in qualifiers for s in chunks):
            for s in chunks:
                if s not in qualifiers: unknown[s]=unknown.get(s,0)+1
            continue
        names={'en':description,'ru':family[1]+(' — '+', '.join(qualifiers[s][0] for s in chunks) if chunks else ''),'kk':family[2]+(' — '+', '.join(qualifiers[s][1] for s in chunks) if chunks else '')}
        item=metadata({'id':'usda-'+row['fdc_id'],'name':names,'kcal':n['1008'],'p':n['1003'],'f':n['1004'],'c':n['1005'],'tags':[],'fdcId':int(row['fdc_id']),'sourceDescription':description},'usda-sr-legacy-2018',False,row['food_category_id'])
        selected.append(item)
    seen=set(); unique=[]
    for item in selected:
        text=item['name']['en'].lower(); states=tuple(w for w in ['raw','uncooked','cooked','boiled','baked','roasted','fried','stewed','canned','frozen','dried','dry','dehydrated','juice pack','water pack','heavy syrup','light syrup','with skin','without skin','nonfat','lowfat','reduced fat','1%','2%','4%','whole milk','part skim'] if w in text); key=(item['name']['ru'].split(' — ')[0],states)
        if key not in seen: seen.add(key); unique.append(item)
    result.extend(unique); add_regional(result); save('foods-v2',result)
    Path('artifacts/food-untranslated-qualifiers.json').write_text(json.dumps(unknown,ensure_ascii=False,indent=2),encoding='utf8')
    print(json.dumps({'legacy':len(old),'usda':len(unique),'total':len(result),'unknown':sorted(unknown.items(),key=lambda row:-row[1])[:60]},ensure_ascii=False))
